import Foundation

struct BackgroundTransferDescriptor {
    let isBackgroundSession: Bool

    var handlerDaemon: String {
        isBackgroundSession ? "nsurlsessiond" : "app-process"
    }
}

let transfer = BackgroundTransferDescriptor(isBackgroundSession: true)
print("Daemon: \(transfer.handlerDaemon)")

import Foundation

struct TaskCompletionLogger {
    func logStatus(success: Bool) -> String {
        success ? "Status: Success" : "Status: Failed"
    }
}

let logger = TaskCompletionLogger()
print(logger.logStatus(success: true))

import Foundation

struct BackgroundTimeEvaluator {
    func timeRemaining(totalGranted: Double, elapsed: Double) -> String {
        let remaining = totalGranted - elapsed
        return String(format: "Remaining: %.1fs", remaining)
    }
}

let evaluator = BackgroundTimeEvaluator()
let output = evaluator.timeRemaining(totalGranted: 30.0, elapsed: 5.0)
print(output)

import Foundation

struct PermittedIdentifierChecker {
    let permittedList = ["com.example.refresh", "com.example.cleanup"]

    func isPermitted(_ id: String) -> Bool {
        permittedList.contains(id)
    }
}

let checker = PermittedIdentifierChecker()
print("Permitted: \(checker.isPermitted("com.example.refresh"))")

